plugins {
    id("com.diffplug.spotless") version "8.11.0" apply false
}

subprojects {
    apply(plugin = "com.diffplug.spotless")

    configure<com.diffplug.gradle.spotless.SpotlessExtension> {
        java {
            target("src/**/*.java")
            // Generated by flatc (gitignored); not ours to format
            targetExclude("src/main/java/org/gatun/protocol/**")
            googleJavaFormat("2.0.0")
            removeUnusedImports()
            trimTrailingWhitespace()
            endWithNewline()
        }
    }
}
